function act(PDO $pdo,$t,$b,$u,$cid,$id,$event,$title,$details){try{$q=$pdo->prepare("INSERT INTO activity_events(tenant_id,branch_id,actor_user_id,actor_type,event_type,related_type,related_id,client_id,title,details_json,visible_to_client) VALUES(:t,:b,:u,'user',:e,'client_location',:r,:c,:title,:d,0)");$q->execute(array(':t'=>$t,':b'=>$b>0?$b:null,':u'=>$u,':e'=>$event,':r'=>$id,':c'=>$cid,':title'=>$title,':d'=>lj($details)));}catch(Throwable $e){error_log('client location activity: '.$e->getMessage());}}
